def length(self, error=ERROR, min_depth=MIN_DEPTH):
        """Calculate the length of the path up to a certain position"""
        if self.is_empty():
            return 0
        if self.is_leaf():
            return 1
        if self.is_root():
            return 1
        if self.is_branch():
            return self.left.length(error, min_depth) + self.right.length(error, min_depth)
        if self.is_node():
